class _Node:
    def __init__(self):
        self.children = {}
        self.content = None  # None for a folder, a string for a file


class FileSystem:
    def __init__(self):
        self.root = _Node()

    def _walk(self, path, create=False):
        node = self.root
        for name in path.split('/'):
            if not name:
                continue
            if name not in node.children:
                if not create:
                    return None
                node.children[name] = _Node()
            node = node.children[name]
        return node

    def mkdir(self, path):
        self._walk(path, create=True)

    def write(self, path, text):
        node = self._walk(path, create=True)
        node.content = (node.content or '') + text

    def read(self, path):
        return self._walk(path).content

    def ls(self, path):
        node = self._walk(path)
        if node.content is not None:
            return [path.rstrip('/').split('/')[-1]]
        return sorted(node.children)

    def size(self, path):
        node = self._walk(path)

        def total(n):
            if n.content is not None:
                return len(n.content)
            return sum(total(c) for c in n.children.values())

        return total(node)

